app.patch('/docs/:id', async (req, res) => {
  const expected = Number(req.get('If-Match')?.replaceAll('"', ''));
  if (!Number.isInteger(expected)) return res.status(428).json({ error: { code: 'PRECONDITION_REQUIRED' } });
  const { rows } = await pool.query(
    'UPDATE docs SET title = $1, version = version + 1 WHERE id = $2 AND version = $3 RETURNING *',
    [req.valid.body.title, req.params.id, expected]
  );
  if (rows.length === 0) return res.status(412).json({ error: { code: 'VERSION_MISMATCH' } });
  res.set('ETag', `"${rows[0].version}"`).json(rows[0]);
});

