export function mapDbError(err) {
  switch (err.code) {
    case '23505':
      return new AppError(409, 'CONFLICT', `Already exists: ${err.constraint}`);
    case '23503':
      return new AppError(409, 'REFERENCE_CONFLICT', 'Related record missing or still in use');
    case '22P02': // invalid text representation, e.g. bad uuid
      return new AppError(400, 'BAD_INPUT', 'Invalid identifier');
    default:
      return err; // unknown: let the error handler log it and return 500
  }
}

